// ─── PARSER & FILTRE ALIMENTAIRE ───────────────────────────────────────────
// Reçoit les réponses de Bonial + Lidl, normalise tout vers le format Firestore
// Structure cible : { item, chain, brand, price_promo, price_normal, unit, valid_until, region, category }

const FOOD_KEYWORDS = [
  'lait','yaourt','fromage','beurre','crème','oeuf','oeufs','feta','mozzarella','camembert',
  'poulet','boeuf','porc','veau','agneau','saumon','thon','crevette','cabillaud','jambon',
  'tomate','carotte','courgette','oignon','salade','poireau','brocoli','poivron','avocat',
  'pomme','banane','orange','poire','fraise','raisin','melon','pêche','citron',
  'pâtes','riz','farine','pain','baguette','céréales','lentilles',
  'huile','sauce','moutarde','mayonnaise','vinaigre','sel','sucre',
  'eau','jus','café','thé','bière','vin','sirop',
  'pizza','surgelé','conserve','haricot','maïs','soupe',
];

const CATEGORY_MAP = [
  [['fruit','légume','légumineuse','tomate','carotte','poivron','salade','courgette','pomme','banane','poire','pêche','fraise'], 'Fruits & Légumes'],
  [['viande','boucherie','poulet','boeuf','porc','veau','agneau','côte','steak','filet','canard'], 'Viandes & Poissons'],
  [['poisson','saumon','thon','crevette','cabillaud','fruits de mer','poissonnerie'], 'Viandes & Poissons'],
  [['lait','yaourt','fromage','beurre','crème','laitier','laitière','oeuf'], 'Produits Laitiers'],
  [['surgelé','congel'], 'Surgelés'],
  [['pain','boulanger','viennoiserie','brioche','baguette'], 'Boulangerie'],
  [['bière','vin','eau','jus','boisson','sodas','café','thé','sirop'], 'Boissons'],
  [['jambon','charcuterie','saucisson','lardons','bacon'], 'Charcuterie'],
];

function guessCategory(name, rawCat) {
  const lower = ((name || '') + ' ' + (rawCat || '')).toLowerCase();
  for (const [keywords, cat] of CATEGORY_MAP) {
    if (keywords.some(k => lower.includes(k))) return cat;
  }
  return 'Épicerie';
}

function isFood(name, rawCat) {
  const lower = ((name || '') + ' ' + (rawCat || '')).toLowerCase();
  return FOOD_KEYWORDS.some(k => lower.includes(k)) ||
    CATEGORY_MAP.some(([kws]) => kws.some(k => lower.includes(k)));
}

function normalizeName(name) {
  if (!name) return '';
  return name
    .replace(/\d+\s*(g|kg|ml|cl|l|litres?|pièces?|unités?|tranches?)\b/gi, '')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, c => c.toUpperCase());
}

function parseDate(raw) {
  if (!raw) return null;
  try {
    return new Date(raw).toISOString().split('T')[0];
  } catch { return null; }
}

function nextSunday() {
  const d = new Date();
  d.setDate(d.getDate() + (7 - d.getDay()) % 7 + 7);
  return d.toISOString().split('T')[0];
}

const deals = [];

for (const input of $input.all()) {
  const raw = input.json;

  // Normalise : peut être un tableau ou { data: [...] } ou { items: [...] } ou { flyers: [...] }
  const list = Array.isArray(raw) ? raw
    : raw.data || raw.items || raw.products || raw.flyers
    || raw.promotions || raw.offers || [];

  for (const entry of list) {
    // Extrait les champs selon différents schémas possibles
    const name = entry.title || entry.name || entry.item || entry.product_name || '';
    const chain = entry.chain || entry.retailer || entry.store || entry.brand_name || entry.store_name || 'Inconnu';
    const brand = entry.brand || entry.manufacturer || null;
    const pricePromo = parseFloat(entry.price || entry.price_promo || entry.pricePromo || entry.regular_price || 0);
    const priceNormal = parseFloat(entry.price_normal || entry.priceNormal || entry.original_price || 0) || null;
    const unit = entry.unit || entry.quantity_label || entry.package || null;
    const rawCat = entry.category || entry.department || '';
    const validUntil = parseDate(entry.valid_until || entry.validTo || entry.end_date || entry.expiry) || nextSunday();

    if (!name.trim() || isNaN(pricePromo) || pricePromo <= 0) continue;
    if (!isFood(name, rawCat)) continue;

    deals.push({
      item: normalizeName(name),
      chain: chain.trim(),
      brand: brand?.trim() || null,
      price_promo: Math.round(pricePromo * 100) / 100,
      price_normal: priceNormal ? Math.round(priceNormal * 100) / 100 : null,
      unit: unit?.trim() || null,
      valid_until: validUntil,
      region: 'national',
      category: guessCategory(name, rawCat),
    });
  }
}

// Dédoublonner : garder le meilleur prix par article+enseigne
const seen = new Map();
const deduped = deals.filter(d => {
  const key = `${d.item.toLowerCase()}-${d.chain.toLowerCase()}`;
  const existing = seen.get(key);
  if (!existing || d.price_promo < existing.price_promo) {
    seen.set(key, d);
    return true;
  }
  return false;
});

return [{ json: { deals: deduped, count: deduped.length } }];
